"""The main password (KAN-29): generated by the app, never typed up by the user.

It replaces the passphrase chosen by hand: a person picks words that can be guessed, a generator does not. The user
chooses only the rules (which kinds of characters, how long, how many digits and symbols at least); the app refuses
rules that would make it weak. Look-alike characters (l, I, O, 0, 1) are left out, so it can be copied by hand.
"""

import math
import secrets
from dataclasses import dataclass
from typing import List

LOWER = "abcdefghijkmnopqrstuvwxyz"
UPPER = "ABCDEFGHJKLMNPQRSTUVWXYZ"
DIGITS = "23456789"
SYMBOLS = "!#$%&*+-=?@^_~"
MIN_LENGTH = 16
MAX_LENGTH = 64
MIN_BITS = 90  # a computer trying every password could not get through 2**90


@dataclass(frozen=True)
class PasswordRules:
    length: int = 20
    lower: bool = True
    upper: bool = True
    digits: bool = True
    symbols: bool = True
    min_digits: int = 2
    min_symbols: int = 2

    def alphabet(self) -> str:
        return (LOWER if self.lower else "") + (UPPER if self.upper else "") + (DIGITS if self.digits else "") + (SYMBOLS if self.symbols else "")

    def bits(self) -> float:
        """Strength in bits, counted as if every character were drawn from the whole alphabet (a slight overestimate
        when minimums are set; MIN_BITS leaves room for it)."""
        alphabet = self.alphabet()
        return self.length * math.log2(len(alphabet)) if alphabet else 0.0

    def problem(self) -> str:
        """'' when these rules make a strong password, else the reason (Italian, for the user)."""
        if not self.alphabet():
            return "scegli almeno un tipo di carattere"
        if not MIN_LENGTH <= self.length <= MAX_LENGTH:
            return f"la lunghezza va da {MIN_LENGTH} a {MAX_LENGTH} caratteri"
        if self.min_digits < 0 or self.min_symbols < 0:
            return "i minimi non possono essere negativi"
        if self.min_digits and not self.digits:
            return "hai chiesto dei numeri ma li hai esclusi"
        if self.min_symbols and not self.symbols:
            return "hai chiesto dei simboli ma li hai esclusi"
        kinds = sum((self.lower, self.upper, self.digits, self.symbols))
        if self.min_digits + self.min_symbols + kinds > self.length:
            return "i minimi non entrano nella lunghezza scelta"
        if self.bits() < MIN_BITS:
            return "con queste regole la password è troppo debole: allungala o aggiungi tipi di caratteri"
        return ""


def generate(rules: PasswordRules = PasswordRules()) -> str:
    """A random password following `rules`: at least one character of each kind chosen, and the minimums."""
    problem = rules.problem()
    if problem:
        raise ValueError(problem)
    picked: List[str] = []
    for enabled, pool, minimum in ((rules.lower, LOWER, 0), (rules.upper, UPPER, 0), (rules.digits, DIGITS, rules.min_digits), (rules.symbols, SYMBOLS, rules.min_symbols)):
        if enabled:
            picked += [secrets.choice(pool) for _ in range(max(1, minimum))]
    alphabet = rules.alphabet()
    picked += [secrets.choice(alphabet) for _ in range(rules.length - len(picked))]
    secrets.SystemRandom().shuffle(picked)
    return "".join(picked)
